import java.util.*;

public class Main {
    static long[] onesSequence = new long[20];
    static long[] powersOf10 = new long[20];
    static int minimalMoves = -1;

    static void setup() {
        powersOf10[0] = 1;
        for (int i = 1; i <= 17; i++) {
            powersOf10[i] = powersOf10[i - 1] * 10;
        }

        onesSequence[0] = 0;
        for (int i = 1; i <= 17; i++) {
            onesSequence[i] = onesSequence[i - 1] * 10 + 1;
        }
    }

    static int getNumberLength(long num) {
        int length = 0;
        do {
            length++;
            num /= 10;
        } while (num != 0);
        return length;
    }

    static void explore(int digitCount, long value, int steps) {
        if (minimalMoves != -1 && steps >= minimalMoves)
            return;
        if (value == 0 || digitCount == 0) {
            if (minimalMoves == -1 || steps < minimalMoves)
                minimalMoves = steps;
            return;
        }
        if (value < 0)
            value = -value;

        long tempValue = value;
        int tempSteps = 0;
        while (tempValue >= powersOf10[digitCount - 1]) {
            tempValue -= onesSequence[digitCount];
            tempSteps += digitCount;
        }
        explore(digitCount - 1, tempValue, steps + tempSteps);

        tempValue = onesSequence[digitCount + 1] - value;
        tempSteps = 0;
        while (tempValue >= powersOf10[digitCount - 1]) {
            tempValue -= onesSequence[digitCount];
            tempSteps += digitCount;
        }
        explore(digitCount - 1, tempValue, steps + digitCount + 1 + tempSteps);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        setup();

        long numInput = sc.nextLong();
        minimalMoves = -1;
        explore(getNumberLength(numInput), numInput, 0);
        System.out.println(minimalMoves);
        sc.close();
    }
}
